            version: number;
            /** Format: date-time */
            effective_from: string;
            source_doc: string;
            /** Format: date-time */
            approved_at: string;
            /** Format: uuid */
            param_version_id: string;
            /** Format: uuid */
            supersedes_id: string | null;
            seq: number;
